   card('ضمن الإمكانات المتاحة', 'شرط مبهم لا يُعرف متى يتحقّق', 'ضمن الإمكانات المتاحة شرط مبهم، ووفق الإجراءات المعتمدة مثله، وتعدّه ريم الأداة الخامسة، ويترجمه حسن: إن وجدنا مالًا.'),
   card('مبنيّ للمجهول', 'فعل بلا فاعل مذكور', 'تُناقش الميزانيات مبنيّ للمجهول، والمجهول يُخفي من يناقش، وتكتب ريم: لا أحد يناقش، ويحوّله فهد إلى سؤال: من يناقشها ومتى؟'),
   card('عموم بدل خصوص', 'جواب عن الكلّ ردًّا على سؤال عن الواحد', 'المتنزّهات أولوية عموم بدل خصوص، وسأل فهد عن متنزّه واحد، وتكتب ريم: اسأل عن متنزّهنا، والبرنامج الشامل عموم.'),
   card('اسم بدل فعل', 'ذكر الشيء موجودًا من غير أن يفعله أحد', 'هناك دراسة اسم بدل فعل، والاسم يوجد والفعل يُسأل عنه، وتفرّق ريم بين هناك دراسة وندرس وننتهي في مارس، ولدينا توجّه مثله.'),
   card('سكوت', 'توقّف حيث لم يكن توقّف', 'سكت المسؤول ثانيتين قبل لم أقل ذلك، والسكوت قرينة، وتسمع ريم السكوت كما تسمع الكلمة، وسكوت حسن في المقهى جواب.'),
