   match('الجملة وأداتها', [('ثمانية أشهر فقط', 'تصغير'), ('وهل نطلب أكثر من خطاب مهذّب؟', 'استفهام إنكاريّ'), ('الصبر مفتاح الفرج', 'مبالغة'), ('في الوقت المناسب، ولم يُفتح بعد', 'اقتباس بجوار الواقع'), ('يا جماعة، المتنزّه مقفول', 'تبدّل السجلّ')]),
