   match('الطالب وقرينته', [('كين', 'الأراجيح'), ('عمر', 'ثمانية أشهر فقط'), ('ليلى', 'وهل نطلب أكثر؟')]),
   order('رتّب قاعدة هند', ['لا', 'سخرية', 'بلا', 'قرينة.']),
