   cloze('أكمل الأدوات الأخرى', 'التصغير بكلمة ___، والاقتباس ___ بجوار الواقع، وتبدّل ___.', ['فقط', 'الحرفيّ', 'السجلّ'], ['جدًّا', 'الطويل', 'العنوان']),
   cloze('أكمل القرينتين', 'القرينة ___ من السياق، والقرينة ___ من النصّ، وفي المكتوب القرينة بدل ___.', ['الخارجية', 'الداخلية', 'النبرة'], ['الأولى', 'الثانية', 'الصورة']),
   cloze('أكمل نصيحة هند', 'الساخر الحاذق يضع ___ واحدًا ___، والساخر الثقيل يكرّره فيصير ___.', ['مفتاحًا', 'مبكّرًا', 'شتمًا'], ['عنوانًا', 'متأخّرًا', 'مدحًا']),
   tf('قرأ كين العمود مرّة واحدة في البداية وفهمه مدحًا.', 'كين قرأه مرّة واحدة وقال: مقال لطيف يمدح البلدية.', 'true', 'الوجه الأوّل.'),
   tf('قالت هند إنّ كلّ مدح للبلدية سخرية.', 'إن لم تجد قرينة لا خارجية ولا داخلية فليست سخرية، بل مدح، ولا تفترض السخرية في كلّ مدح لا يعجبك.', 'false', 'لا سخرية بلا قرينة.'),
   tf('ردّت البلدية على عمود نورة.', 'وأشكرها على ردّها على خطاب أبي فيصل، فقد قرأته ثلاث مرّات.', 'ng', 'لم يُذكر ردّ على العمود.'),
   tap('المس كلمة التصغير', ['فمنذ', 'ثمانية', 'أشهر', 'فقط', 'أُغلق'], 'فقط'),
   tap('المس الكلمة التي تكشف تبدّل السجلّ', ['يا', 'جماعة،', 'المتنزّه', 'مقفول.', 'وشكرًا'], 'مقفول.'),
   tap('المس القرينة الداخلية الأولى', ['صمدت', 'أطول', 'ممّا', 'صمدت', 'الأراجيح'], 'الأراجيح'),
   dic('لا سخرية بلا قرينة.', ['لا سخرية بلا قرينة', 'لا سخريه بلا قرينه']),
